# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: One browser tab's working session, with no UI code: a persistent
#          Python namespace, the agent conversation, and the tables the agent's
#          tools return (bound into the namespace as r1, r2, ...).
# Usage: get_session(token).run_python(code) / await get_session(token).ask(prompt, on_delta)
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import contextlib
import io
import traceback
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any

import ds.ai
import ds.data
import jedi
import polars as pl
from pydantic_ai import capture_run_messages
from pydantic_ai.messages import ToolCallPart, ToolReturnPart

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable

MAX_GRID_ROWS = 2000
MAX_COMPLETIONS = 60
MAX_ARGS_CHARS = 160
# Names put in the namespace up front; never listed as data objects.
BUILTIN_NAMES = ("pl", "db")


@dataclass
class PyResult:
    stdout: str = ""
    result_repr: str = ""
    error: str = ""
    frame: pl.DataFrame | None = None
    """Set instead of result_repr when the cell's value is tabular, so it renders as a grid."""


@dataclass
class ToolStep:
    tool: str
    args: str
    result_name: str = ""
    """Name the returned table was bound to (eg 'r1'), '' when the tool returned no table."""


@dataclass
class AiResult:
    text: str = ""
    error: str = ""
    steps: list[ToolStep] = field(default_factory=list)


class Session:
    def __init__(self) -> None:
        self.namespace: dict[str, Any] = {"__name__": "__main__", "pl": pl, "db": ds.data.init_db()}
        self.ai_history: list[Any] = []
        self.sources: dict[str, str] = {}
        # Tabular results of notebook cells, by cell id, so their grids can be re-sorted.
        self.outputs: dict[str, pl.DataFrame] = {}
        self._table_count = 0

    # -- python ---------------------------------------------------------------

    def run_python(self, code: str) -> PyResult:
        """Run code in the persistent namespace; a trailing bare expression is the result, as in Jupyter."""
        result = PyResult()
        try:
            tree = ast.parse(code, mode="exec")
        except SyntaxError:
            result.error = traceback.format_exc(limit=0)
            return result
        trailing = tree.body.pop() if tree.body and isinstance(tree.body[-1], ast.Expr) else None
        stdout = io.StringIO()
        try:
            with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stdout):
                if tree.body:
                    exec(compile(tree, "<cell>", "exec"), self.namespace)  # noqa: S102  # a REPL runs user code
                if trailing is not None:
                    value = eval(compile(ast.Expression(trailing.value), "<cell>", "eval"), self.namespace)  # noqa: S307
                    if value is not None:
                        self.namespace["_"] = value
                        result.frame = as_frame(value)
                        if result.frame is None:
                            result.result_repr = repr(value)
        except Exception as error:  # noqa: BLE001  # any user error is shown under the cell, not raised
            # drop this function's own frame so the traceback starts at the user's code
            tb = error.__traceback__.tb_next if error.__traceback__ else None
            result.error = "".join(traceback.format_exception(type(error), error, tb))
        result.stdout = stdout.getvalue()
        return result

    # -- data objects -----------------------------------------------------------

    def frames(self) -> dict[str, pl.DataFrame]:
        """Every DataFrame bound to a public name, whether the agent or the user made it."""
        return {
            name: value
            for name, value in self.namespace.items()
            if isinstance(value, pl.DataFrame) and not name.startswith("_") and name not in BUILTIN_NAMES
        }

    def bind_table(self, df: pl.DataFrame, source: str) -> str:
        self._table_count += 1
        name = f"r{self._table_count}"
        self.namespace[name] = df
        self.sources[name] = source
        return name

    # -- agent ------------------------------------------------------------------

    async def ask(self, prompt: str, on_delta: Callable[[str], Awaitable[None]]) -> AiResult:
        """One agent turn. Text streams through on_delta; tables its tools return become r1, r2, ..."""
        result = AiResult()
        with capture_run_messages() as captured:
            try:
                async with ds.ai.agent.run_stream(prompt, message_history=self.ai_history) as stream:
                    async for delta in stream.stream_text(delta=True):
                        await on_delta(delta)
                    result.text = str(await stream.get_output())
                    new_messages = stream.new_messages()
                    self.ai_history = stream.all_messages()
            except Exception:  # noqa: BLE001  # model/tool failures are shown in the chat
                result.error = traceback.format_exc(limit=4)
                new_messages = captured[len(self.ai_history) :]
        result.steps = self._steps(new_messages)
        return result

    def _steps(self, messages: list[Any]) -> list[ToolStep]:
        steps: dict[str, ToolStep] = {}
        for message in messages:
            for part in message.parts:
                if isinstance(part, ToolCallPart):
                    args = part.args_as_json_str()
                    if len(args) > MAX_ARGS_CHARS:
                        args = args[:MAX_ARGS_CHARS] + "…"
                    steps[part.tool_call_id] = ToolStep(tool=part.tool_name, args=args)
                elif isinstance(part, ToolReturnPart) and isinstance(part.content, ds.ai.TableResult):
                    name = self.bind_table(part.content.to_df(), part.tool_name)
                    if part.tool_call_id in steps:
                        steps[part.tool_call_id].result_name = name
        return list(steps.values())


def as_frame(value: Any) -> pl.DataFrame | None:
    """The value as a polars DataFrame if it is tabular (polars DataFrame/Series, pandas DataFrame), else None."""
    if isinstance(value, pl.DataFrame):
        return value
    if isinstance(value, pl.Series):
        return value.to_frame()
    if type(value).__module__.startswith("pandas") and type(value).__name__ in {"DataFrame", "Series"}:
        with contextlib.suppress(Exception):  # odd pandas dtypes polars can't take: fall back to repr
            return pl.from_pandas(value)
    return None


def dtype_label(dtype: pl.DataType) -> str:
    """Polars' short dtype name as in its table repr: i64, f64, str, list[str], datetime[μs]."""
    with contextlib.suppress(Exception):  # private polars helper; fall back to the long name
        return dtype._string_repr()
    return str(dtype)


def _column_width(title: str, column: pl.Series) -> int:
    """Pixel width (12px mono) that fits the header title or the longest of the first 200 values."""
    sample = column.head(200).cast(pl.String, strict=False).fill_null("").to_list()
    longest = max([len(title) + 1, *(len(value) for value in sample)])
    return max(48, min(240, round(7.3 * longest) + 18))


def grid_data(
    df: pl.DataFrame, query: str, sort_col: str, descending: bool
) -> tuple[list[dict[str, Any]], list[list[Any]]]:
    """Filter and sort df, then shape it for the grid: (columns, rows), capped at MAX_GRID_ROWS."""
    if query:
        with contextlib.suppress(Exception):  # columns that can't be shown as text just don't match
            text = pl.concat_str(pl.all().cast(pl.String, strict=False).fill_null(""), separator=" ")
            df = df.filter(text.str.to_lowercase().str.contains(query.lower(), literal=True))
    if sort_col in df.columns:
        with contextlib.suppress(Exception):  # unsortable dtypes stay in original order
            df = df.sort(sort_col, descending=descending, nulls_last=True)
    df = df.head(MAX_GRID_ROWS)

    columns: list[dict[str, Any]] = []
    numeric: list[bool] = []
    for name, dtype in df.schema.items():
        # The grid's number cells can't show nulls, so only null-free numeric columns stay numbers.
        is_number = (
            dtype.is_numeric() and df[name].null_count() == 0 and not (dtype.is_float() and df[name].is_nan().any())
        )
        numeric.append(is_number)
        arrow = (" ▼" if descending else " ▲") if name == sort_col else ""
        label = dtype_label(dtype)
        columns.append(
            {
                "title": name + arrow,
                "id": name,
                # read by the grid's DRAW_HEADER (reflex_kernel.py): dtype on a second, italic line
                "dtype": label,
                "type": ("float" if dtype.is_float() else "int") if is_number else "str",
                # fixed widths sized to content, with room for the sort arrow
                "width": _column_width(max(f"{name} ▲", label, key=len), df[name]),
            }
        )
    rows = [
        [value if numeric[i] else ("" if value is None else str(value)) for i, value in enumerate(row)]
        for row in df.rows()
    ]
    return columns, rows


_SESSIONS: dict[str, Session] = {}


def get_session(token: str) -> Session:
    """The session for a browser tab, created on first use. Lives in server memory only."""
    if token not in _SESSIONS:
        _SESSIONS[token] = Session()
    return _SESSIONS[token]


def complete(token: str, code: str, line: int, column: int) -> list[dict[str, str]]:
    """Completions at (1-based line, 0-based column) of code, resolved against the session's live variables.

    Uses jedi's Interpreter mode, like IPython: `r1.` completes with real DataFrame methods because
    r1 exists. An unknown token completes against an empty namespace instead of creating a session.
    """
    session = _SESSIONS.get(token)
    namespace = session.namespace if session else {}
    try:
        found = jedi.Interpreter(code, [namespace]).complete(line, column)
    except Exception:  # noqa: BLE001  # completion is best-effort; never break typing
        return []
    public = [item for item in found if not item.name.startswith("_")] or found
    return [{"label": item.name, "type": item.type, "detail": item.type} for item in public[:MAX_COMPLETIONS]]
